list=["mobile="+mobile,"packageName=com.fuxiuyuedu.fuzReader","time="+time,"token=","marketChannel=vivo","appId=","sysVer=7.1.2","osType=2","udid=1f705dac-2eec-3045-96be-713264df32c2","ver=1.0.0","product=1"];
